css:
/* ---------- v9: phone hero film, centred; services grid ---------- */
@media(min-width:761px){.ig-row{grid-template-columns:repeat(4,1fr)!important;gap:16px!important}}
@media(max-width:760px){
  #hero{min-height:640px}
  .hz{inset:0;height:auto}
  .hz img,.hz video{object-position:50% 50%}
  #hBefore,.hedge,.hlab,.hshade{display:none}
  #hImg{clip-path:none!important;transform:none!important}
  .hz::after{inset:0;height:auto;background:linear-gradient(180deg,rgba(8,10,9,.55) 0%,rgba(8,10,9,.08) 24%,rgba(8,10,9,.42) 50%,rgba(8,10,9,.94) 100%)}
  .hc{bottom:66px;text-align:center}
  .hl{display:flex;flex-direction:column;align-items:center}
  .pill{background:rgba(20,24,21,.5)}
  .hero-h{font-size:clamp(60px,18vw,86px);margin:16px 0 14px}
  .hero-p{max-width:31ch;margin:0 auto;color:rgba(255,255,255,.8)}
  .hero-b{width:100%;margin-top:24px}
  .hero-n{justify-content:center;margin-top:16px}
  .sg{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px 12px;overflow:visible;margin:0;padding:0;scroll-snap-type:none}
  .sc{flex:none}
  .sc .im{aspect-ratio:1/1.1;border-radius:20px}
  .sc .tx{padding:12px 0 0;gap:0}
  .sc h3{font-size:17px;line-height:1.15}
  .sc p{display:none}
  .sc .go{font-size:13px;margin-top:6px}
}

menucss:
/* menu v2: a photo strip per service */
.x-sheet .ms{display:grid;gap:8px}
.x-sheet a.sv{position:relative;display:flex;align-items:center;justify-content:space-between;height:60px;padding:0 18px;border-radius:18px;overflow:hidden;isolation:isolate;background:#171B18;color:#fff;font-size:19px;font-weight:600;letter-spacing:-.03em;text-decoration:none;transform:translateY(14px);opacity:0;transition:transform .7s cubic-bezier(.22,1,.36,1),opacity .6s}
.x-sheet.on a.sv{transform:none;opacity:1}
.x-sheet a.sv:nth-child(2){transition-delay:.04s}.x-sheet a.sv:nth-child(3){transition-delay:.08s}.x-sheet a.sv:nth-child(4){transition-delay:.12s}.x-sheet a.sv:nth-child(5){transition-delay:.16s}.x-sheet a.sv:nth-child(6){transition-delay:.2s}.x-sheet a.sv:nth-child(7){transition-delay:.24s}
.x-sheet a.sv img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}
.x-sheet a.sv::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(10,13,11,.84) 0%,rgba(10,13,11,.58) 50%,rgba(10,13,11,.34) 100%)}
.x-sheet a.sv svg{width:16px;height:16px;flex:none;opacity:.85}
.x-sheet a.sv:active{transform:scale(.98)}
.x-sheet .ar{display:flex;flex-wrap:wrap;gap:8px}
.x-sheet .ar a{display:inline-flex;align-items:center;height:40px;padding:0 15px;border-radius:999px;border:1px solid rgba(17,20,18,.16);font-size:14.5px;font-weight:500;color:#111412;text-decoration:none}
.x-sheet .mr{display:flex;flex-wrap:wrap;gap:6px 20px}
.x-sheet .mr a{font-size:16px;font-weight:600;letter-spacing:-.02em;color:#111412;text-decoration:underline;text-underline-offset:4px;text-decoration-color:rgba(17,20,18,.25);padding:4px 0}
